mapper.select:
SELECT 
FROM w17_noncash_award a JOIN w17_noncash_pledge p ON p.pledge_id=a.pledge_id
WHERE a.member_id=#{memberId} AND a.award_id=#{awardId}

SELECT 
FROM w17_noncash_award a JOIN w17_noncash_pledge p ON p.pledge_id=a.pledge_id
WHERE a.member_id=#{memberId}

  AND (a.awarded_at < #{beforeTime} OR (a.awarded_at=#{beforeTime} AND a.award_id < #{beforeId}))

ORDER BY a.awarded_at DESC, a.award_id DESC
LIMIT #{fetchSize}
